/* ========================================
   Volta Studio — Stylesheet
   ======================================== */

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --color-bg: #F5F2ED;
  --color-text: #1A1A1A;
  --color-text-muted: #6B6560;
  --color-accent: #C4725A;
  --color-divider: #D9D4CD;
  --font-serif: 'Playfair Display', Georgia, serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 2rem;
  --space-lg: 4rem;
  --space-xl: 6rem;
  --space-2xl: 10rem;
  --max-width: 1320px;
  --reading-width: 680px;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-weight: 400;
  line-height: 1.7;
  color: var(--color-text);
  background-color: var(--color-bg);
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* ========================================
   Header & Navigation
   ======================================== */

.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background-color: var(--color-bg);
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 1.5rem 2.5rem;
}

.nav-logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
}

.nav-links {
  display: flex;
  list-style: none;
  gap: 2.5rem;
}

.nav-links a {
  font-size: 0.875rem;
  font-weight: 400;
  letter-spacing: 0.02em;
  color: var(--color-text-muted);
  transition: color 0.3s ease;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--color-text);
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 6px;
  width: 32px;
  height: 32px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  z-index: 200;
}

.hamburger-line {
  display: block;
  width: 24px;
  height: 1.5px;
  background-color: var(--color-text);
  transition: transform 0.3s ease, opacity 0.3s ease;
  transform-origin: center;
}

.hamburger.is-active .hamburger-line:first-child {
  transform: translateY(3.75px) rotate(45deg);
}

.hamburger.is-active .hamburger-line:last-child {
  transform: translateY(-3.75px) rotate(-45deg);
}

/* Mobile overlay */
.mobile-overlay {
  position: fixed;
  inset: 0;
  z-index: 150;
  background-color: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.4s ease, visibility 0.4s ease;
}

.mobile-overlay.is-open {
  opacity: 1;
  visibility: visible;
}

.mobile-nav-links {
  list-style: none;
  text-align: center;
}

.mobile-nav-links li {
  margin-bottom: 1.5rem;
}

.mobile-nav-links a {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-text);
  transition: color 0.3s ease;
}

.mobile-nav-links a:hover {
  color: var(--color-accent);
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }
  .hamburger {
    display: flex;
  }
}

/* ========================================
   Hero
   ======================================== */

.hero {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 10rem 2.5rem 4rem;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 5.5rem);
  font-weight: 900;
  line-height: 1.08;
  letter-spacing: -0.03em;
  max-width: 900px;
  color: var(--color-text);
}

/* ========================================
   Media Showcase
   ======================================== */

.media-showcase {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 2rem 2.5rem var(--space-xl);
}

.media-grid {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr 1fr;
  gap: 1.25rem;
  height: clamp(280px, 40vw, 500px);
}

.media-block {
  border-radius: 4px;
}

@media (max-width: 768px) {
  .media-grid {
    grid-template-columns: 1fr;
    height: auto;
    gap: 1rem;
  }
  .media-block {
    height: 200px;
  }
}

/* ========================================
   Client Marquee
   ======================================== */

.client-marquee {
  padding: var(--space-lg) 0;
  overflow: hidden;
  border-top: 1px solid var(--color-divider);
  border-bottom: 1px solid var(--color-divider);
}

.marquee-row {
  display: flex;
  overflow: hidden;
  white-space: nowrap;
  margin: 0.75rem 0;
}

.marquee-track {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  min-width: 100%;
}

.marquee-track span {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3.5vw, 3rem);
  font-weight: 700;
  letter-spacing: -0.01em;
  padding: 0 0.5rem;
  color: var(--color-text);
}

.marquee-track .separator {
  font-size: clamp(1rem, 2vw, 1.5rem);
  color: var(--color-text-muted);
  padding: 0 1rem;
  font-weight: 400;
}

/* Marquee Left (Row 1, Row 3) */
.marquee-left .marquee-track {
  animation: marquee-scroll-left 30s linear infinite;
}

.marquee-slow .marquee-track {
  animation-duration: 40s;
}

/* Marquee Right (Row 2) */
.marquee-right .marquee-track {
  animation: marquee-scroll-right 35s linear infinite;
}

@keyframes marquee-scroll-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-scroll-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

/* ========================================
   About
   ======================================== */

.about {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: var(--space-2xl) 2.5rem;
}

.about-inner {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: var(--space-lg);
  max-width: 960px;
}

.about-label {
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  padding-top: 0.35rem;
}

.about-content p {
  font-size: 1.125rem;
  line-height: 1.8;
  margin-bottom: 1.5rem;
  color: var(--color-text);
}

.about-content p:last-child {
  margin-bottom: 0;
}

@media (max-width: 768px) {
  .about-inner {
    grid-template-columns: 1fr;
    gap: var(--space-sm);
  }
}

/* ========================================
   Founder Letter (Neweno)
   ======================================== */

.founder-letter {
  max-width: var(--reading-width);
  margin: 0 auto;
  padding: 10rem 2rem var(--space-2xl);
}

.letter-header {
  margin-bottom: var(--space-xl);
}

.letter-label {
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-text-muted);
  margin-bottom: var(--space-sm);
}

.letter-title {
  font-family: var(--font-serif);
  font-size: clamp(3rem, 8vw, 6rem);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: -0.03em;
  color: var(--color-text);
}

.letter-body p {
  font-size: 1.125rem;
  line-height: 1.85;
  margin-bottom: 1.75rem;
  color: var(--color-text);
}

.letter-greeting {
  font-family: var(--font-serif);
  font-size: 1.75rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 2rem !important;
  color: var(--color-text);
}

.letter-pullquote {
  margin: 3rem 0;
  padding-left: 2rem;
  border-left: 3px solid var(--color-accent);
}

.letter-pullquote p {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 400;
  font-style: italic;
  line-height: 1.5;
  color: var(--color-text);
  margin-bottom: 0 !important;
}

.letter-sign-off {
  font-family: var(--font-serif);
  font-size: 2rem;
  font-weight: 900;
  font-style: italic;
  margin-top: 3rem !important;
  color: var(--color-accent);
}

.letter-signature {
  margin-top: 3rem !important;
  font-weight: 500;
  line-height: 1.6;
}

.signature-title {
  font-weight: 400;
  color: var(--color-text-muted);
  font-size: 0.9375rem;
}

/* ========================================
   Philosophy (Services)
   ======================================== */

.philosophy {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 10rem 2.5rem var(--space-xl);
}

.philosophy-inner {
  max-width: 800px;
}

.philosophy-title {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-lg);
  color: var(--color-text);
}

.philosophy-text p {
  font-size: 1.125rem;
  line-height: 1.85;
  margin-bottom: 1.5rem;
  color: var(--color-text);
}

.section-divider {
  border: none;
  border-top: 1px solid var(--color-divider);
  max-width: var(--max-width);
  margin: 0 auto;
  margin-left: 2.5rem;
  margin-right: 2.5rem;
}

/* ========================================
   Service Details
   ======================================== */

.service-details {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: var(--space-xl) 2.5rem var(--space-2xl);
}

.service-details-inner {
  max-width: 800px;
}

.service-details-heading {
  font-family: var(--font-serif);
  font-size: clamp(1.75rem, 4vw, 2.75rem);
  font-weight: 700;
  font-style: italic;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-xl);
  color: var(--color-text);
}

.service-item {
  margin-bottom: var(--space-lg);
}

.service-name {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: var(--space-sm);
  color: var(--color-text);
}

.service-item p {
  font-size: 1.0625rem;
  line-height: 1.85;
  color: var(--color-text-muted);
}

/* ========================================
   Clients
   ======================================== */

.clients-section {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 10rem 2.5rem var(--space-2xl);
}

.clients-heading {
  margin-bottom: var(--space-xl);
}

.clients-title {
  font-family: var(--font-serif);
  font-size: clamp(3rem, 7vw, 6rem);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: -0.03em;
  color: var(--color-text);
}

.clients-subtitle {
  font-size: 1.125rem;
  color: var(--color-text-muted);
  margin-top: 0.75rem;
  font-style: italic;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2.5rem 3rem;
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  color: var(--color-text);
}

.client-card p {
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--color-text-muted);
}

@media (max-width: 1024px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .clients-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
}

/* ========================================
   Contact
   ======================================== */

.contact-section {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 10rem 2.5rem var(--space-2xl);
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
}

.contact-hero {
  margin-bottom: var(--space-lg);
}

.contact-title {
  font-family: var(--font-serif);
  font-size: clamp(5rem, 15vw, 14rem);
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.04em;
  color: var(--color-text);
}

.contact-links {
  display: flex;
  gap: 2.5rem;
  justify-content: center;
  flex-wrap: wrap;
}

.contact-link {
  font-family: var(--font-sans);
  font-size: 1.125rem;
  font-weight: 400;
  color: var(--color-text-muted);
  transition: color 0.3s ease;
  position: relative;
}

.contact-link::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 1px;
  background-color: var(--color-text);
  transition: width 0.3s ease;
}

.contact-link:hover {
  color: var(--color-text);
}

.contact-link:hover::after {
  width: 100%;
}

/* ========================================
   Footer
   ======================================== */

.site-footer {
  border-top: 1px solid var(--color-divider);
  padding: var(--space-md) 2.5rem;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-logo {
  font-family: var(--font-serif);
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-text);
}

.footer-copy {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

/* ========================================
   Responsive Utilities
   ======================================== */

@media (max-width: 768px) {
  .hero {
    padding: 7rem 1.5rem 3rem;
  }
  .media-showcase {
    padding: 1.5rem 1.5rem var(--space-lg);
  }
  .about {
    padding: var(--space-xl) 1.5rem;
  }
  .founder-letter {
    padding: 7rem 1.5rem var(--space-xl);
  }
  .philosophy {
    padding: 7rem 1.5rem var(--space-lg);
  }
  .service-details {
    padding: var(--space-lg) 1.5rem var(--space-xl);
  }
  .section-divider {
    margin-left: 1.5rem;
    margin-right: 1.5rem;
  }
  .clients-section {
    padding: 7rem 1.5rem var(--space-xl);
  }
  .contact-section {
    padding: 7rem 1.5rem var(--space-xl);
  }
  .nav {
    padding: 1.25rem 1.5rem;
  }
  .site-footer {
    padding: var(--space-md) 1.5rem;
  }
  .footer-inner {
    flex-direction: column;
    gap: 0.5rem;
    text-align: center;
  }
}

