.media-grid {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr 1fr;
  gap: 1.25rem;
  height: clamp(280px, 40vw, 500px);
}

.media-block {
  border-radius: 4px;
}

@media (max-width: 768px) {
  .media-grid {
    grid-template-columns: 1fr;
    height: auto;
    gap: 1rem;
  }
  .media-block {
    height: 200px;
  }
}

