.client-card h3 {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  color: var(--color-text);
}

.client-card p {
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--color-text-muted);
}

